//
// The forti MCP workspace: project scope in the forti home (~/.forti, $FORTI_HOME). An agent started
// there (`cd ~/.forti && claude`, or `codex`) gets the FortiGate tools; an agent started anywhere else
// does not. Besides the registration (.mcp.json, .codex/config.toml, done by the adapters) and the
// skill, a workspace install keeps a small scaffold in the home:
//
//   AGENTS.md, CLAUDE.md (@AGENTS.md)   what the directory is, generated by `forti mcp install`
//   .claude/settings.json               permissions.deny rules: no reading credentials/ or certificate
//                                       keys, no editing config.json (merged into the person's file)
//   .codex/config.toml                  default_permissions = "forti-workspace", a permission profile that
//                                       denies the same paths to sandboxed commands
//   $CODEX_HOME/config.toml             [projects."<home>"] trust_level = "trusted", only with consent
//   .forti-workspace.json               what forti wrote (hashes, rules, trust), so uninstall removes
//                                       exactly that and an edited file is never overwritten
//
// Never touched: config.json, credentials/, certs/, state/, cache/.
//

#ifndef FORTI_INSTALL_WORKSPACE_HPP
#define FORTI_INSTALL_WORKSPACE_HPP

#include "client.hpp"

#include <nlohmann/json.hpp>

#include <functional>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace forti::install::workspace {

    inline constexpr std::string_view marker_file = ".forti-workspace.json";
    inline constexpr std::string_view codex_profile = "forti-workspace";

    // One file or setting of the scaffold.
    //   install states:   create, update, ok, conflict (left alone), trust, untrusted (no consent)
    //   uninstall states: remove, kept (not ours or edited: left alone)
    struct Item {
        std::string name;      // "AGENTS.md", "Claude Code deny rules", "Codex trust"...
        fs::path path;
        std::string state;
        std::string message;
        std::vector<Action> actions;
    };

    // Claude Code permission rules in <home>/.claude/settings.json. A leading `/` anchors a rule to the
    // directory of the project settings file (code.claude.com/docs/en/permissions, "Read and Edit").
    const std::vector<std::string>& claude_deny_rules();

    // AGENTS.md and CLAUDE.md for this home.
    std::string agents_md(const Context& context);
    std::string claude_md();

    // Creates the forti home (0700) when it does not exist yet; nullopt when it does.
    std::optional<Action> create_home(const Context& context);

    // The scaffold a workspace install adds for `client`; `shared` adds AGENTS.md too.
    // `trust_codex`: the person agreed to mark the forti home trusted in the global Codex config.
    std::vector<Item> plan_install(const ClientAdapter& client, bool shared, bool trust_codex, const Context& context);

    // What uninstall removes: only what forti wrote. `shared` also removes AGENTS.md (when no other
    // client stays registered in the workspace).
    std::vector<Item> plan_uninstall(const ClientAdapter& client, bool shared, const Context& context);

    // Codex trusts the forti home ([projects."<home>"] trust_level = "trusted" in the global config).
    bool codex_trusted(const Context& context);
    // Asking for trust makes sense: Codex does not trust the home and has no entry for it at all (an
    // entry the person wrote, e.g. trust_level = "untrusted", is their decision and is left alone).
    bool codex_trust_needed(const Context& context);

    // `forti mcp status`: the home and the health of every scaffold file.
    nlohmann::json status(const Context& context);

    // ---- The home directory guard ----

    // A project or local install whose directory is $HOME itself (and not the forti home) would give the
    // firewall tools to an agent started anywhere under the home directory. The warning, else nullopt.
    std::optional<std::string> home_directory_warning(Scope scope, const Context& context);

    // Applies the guard. Interactive: shows the warning and asks "Are you sure?" (default No); false
    // when declined. Otherwise refuses with Failure(policy_denied) unless `force`.
    bool allow_home_directory(Scope scope, const Context& context, bool interactive, bool force,
                              const std::function<void(std::string_view)>& say,
                              const std::function<bool(std::string_view, bool)>& confirm);

}  // namespace forti::install::workspace

#endif  // FORTI_INSTALL_WORKSPACE_HPP
